import { useState, FormEvent } from 'react';
import {
  JxStepper,
  JxInputField,
  JxButton,
  JxAlert,
  JxDivider,
} from '@jinx-ui/react';

interface ContactsData {
  name: string;
  email: string;
}

interface AddressData {
  city: string;
  street: string;
  zip: string;
}

interface RegistrationData extends ContactsData, AddressData {}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [contacts, setContacts] = useState<ContactsData>({ name: '', email: '' });
  const [address, setAddress] = useState<AddressData>({ city: '', street: '', zip: '' });
  const [touchedStep, setTouchedStep] = useState<number | null>(null);

  const nameError = touchedStep === 0 && contacts.name.trim().length === 0 ? 'Укажите имя' : undefined;
  const emailError =
    touchedStep === 0 && contacts.email.length > 0 && !contacts.email.includes('@')
      ? 'Укажите адрес с символом @'
      : touchedStep === 0 && contacts.email.trim().length === 0
      ? 'Укажите почту'
      : undefined;
  const cityError = touchedStep === 1 && address.city.trim().length === 0 ? 'Укажите город' : undefined;
  const streetError = touchedStep === 1 && address.street.trim().length === 0 ? 'Укажите улицу и дом' : undefined;
  const zipError = touchedStep === 1 && address.zip.trim().length === 0 ? 'Укажите индекс' : undefined;

  const contactsValid = contacts.name.trim().length > 0 && contacts.email.includes('@');
  const addressValid = address.city.trim().length > 0 && address.street.trim().length > 0 && address.zip.trim().length > 0;

  const goNext = () => {
    if (step === 0) {
      if (!contactsValid) {
        setTouchedStep(0);
        return;
      }
      setTouchedStep(null);
      setStep(1);
      return;
    }
    if (step === 1) {
      if (!addressValid) {
        setTouchedStep(1);
        return;
      }
      setTouchedStep(null);
      setStep(2);
    }
  };

  const goBack = () => {
    setTouchedStep(null);
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSubmit({ ...contacts, ...address });
  };

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px', maxWidth: '480px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={contacts.name}
            onChange={(event) => setContacts((prev) => ({ ...prev, name: event.target.value }))}
            errorText={nameError}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={contacts.email}
            onChange={(event) => setContacts((prev) => ({ ...prev, email: event.target.value }))}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Город"
            required
            value={address.city}
            onChange={(event) => setAddress((prev) => ({ ...prev, city: event.target.value }))}
            errorText={cityError}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={address.street}
            onChange={(event) => setAddress((prev) => ({ ...prev, street: event.target.value }))}
            errorText={streetError}
          />
          <JxInputField
            label="Индекс"
            required
            value={address.zip}
            onChange={(event) => setAddress((prev) => ({ ...prev, zip: event.target.value }))}
            errorText={zipError}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxAlert intent="info" title="Проверьте данные перед отправкой">
            Если что-то не так, вернитесь на предыдущий шаг и исправьте.
          </JxAlert>
          <JxDivider label="Контакты" />
          <dl style={{ display: 'flex', flexDirection: 'column', gap: '4px', margin: 0 }}>
            <div style={{ display: 'flex', gap: '8px' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Имя:</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{contacts.name}</dd>
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Почта:</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{contacts.email}</dd>
            </div>
          </dl>
          <JxDivider label="Адрес" />
          <dl style={{ display: 'flex', flexDirection: 'column', gap: '4px', margin: 0 }}>
            <div style={{ display: 'flex', gap: '8px' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Город:</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{address.city}</dd>
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Улица и дом:</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{address.street}</dd>
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>Индекс:</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{address.zip}</dd>
            </div>
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < 2 ? (
          <JxButton type="button" variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

